<script setup> /** * Vue permettant de réinitialiser le mot de passe après avoir cliqué sur le lien reçu par e-mail. */ import { ref, onMounted } from'vue' import { useRoute, useRouter } from'vue-router' import api from'../services/api' import { Key, Loader2, CheckCircle2, AlertCircle, Eye, EyeOff } from'lucide-vue-next' const route = useRoute() const router = useRouter() const token = ref(route.params.token ||'') const newPassword = ref('') const confirmPassword = ref('') const showPassword = ref(false) const loading = ref(false) const error = ref('') const success = ref(false) const handleSubmit = async () => { error.value ='' success.value = false if (!token.value) { error.value ="Le lien de réinitialisation est invalide." return } if (newPassword.value !== confirmPassword.value) { error.value ="Les deux mots de passe ne correspondent pas." return } if (newPassword.value.length < 8) { error.value ="Le mot de passe doit contenir au moins 8 caractères." return } loading.value = true try { await api.post('auth/reinit-mdp/confirmer/', { token: token.value, nouveau_mot_de_passe: newPassword.value, confirmation: confirmPassword.value, }) success.value = true } catch (err) { error.value = err.response?.data?.token || err.response?.data?.nouveau_mot_de_passe || err.response?.data?.detail ||"Le lien a expiré ou est invalide." } finally { loading.value = false } } </script> <template> <div class="min-h-screen flex items-center justify-center bg-[#FFFFFF] p-4 sm:p-6 lg:p-8"> <div class="max-w-md w-full bg-white rounded-3xl border border-[#01313E]/10 p-8 sm:p-10 space-y-6"> <div class="text-center space-y-2"> <div class="w-12 h-12 bg-white text-[#E30046] rounded-2xl flex items-center justify-center mx-auto mb-3"> <Key class="w-6 h-6"/> </div> <h2 class="text-2xl font-extrabold text-[#01313E] tracking-tight">Nouveau Mot de Passe</h2> <p class="text-xs text-[#01313E]/60 max-w-xs mx-auto"> Définissez un nouveau mot de passe sécurisé pour votre compte Simplon. </p> </div> <div v-if="success"class="bg-white border border-[#01313E] text-[#01313E] p-5 rounded-2xl text-xs space-y-3"> <div class="flex items-center gap-2 font-bold text-[#01313E] text-sm"> <CheckCircle2 class="w-5 h-5 text-[#01313E] flex-shrink-0"/> <span>Mot de passe modifié avec succès !</span> </div> <p class="text-[#01313E]"> Votre mot de passe a été réinitialisé. Vous pouvez désormais vous connecter avec votre nouveau mot de passe. </p> <button @click="router.push('/login')" class="w-full mt-2 py-3 bg-[#E30046] hover:bg-[#C7003D] text-white rounded-xl text-xs font-bold transition-colors -[#E30046]/20" > Se connecter </button> </div> <form v-else @submit.prevent="handleSubmit"class="space-y-4"> <div v-if="error"class="bg-white border border-[#E30046] text-[#E30046] p-3 rounded-xl text-xs flex items-center gap-2"> <AlertCircle class="w-4 h-4 text-[#E30046] flex-shrink-0"/> <span>{{ error }}</span> </div> <div> <label class="block text-xs font-bold text-[#01313E] mb-1">Nouveau mot de passe</label> <div class="relative"> <input :type="showPassword ?'text' :'password'" v-model="newPassword" required placeholder="Au moins 8 caractères" class="w-full px-4 py-2.5 border border-[#01313E]/10 rounded-xl text-sm focus:outline-none focus:ring-2 focus:focus:border-[#E30046]" /> <button type="button" @click="showPassword = !showPassword" class="absolute right-3 top-1/2 -translate-y-1/2 text-[#01313E]/60 hover:text-[#01313E]/80" > <EyeOff v-if="showPassword"class="w-4 h-4"/> <Eye v-else class="w-4 h-4"/> </button> </div> </div> <div> <label class="block text-xs font-bold text-[#01313E] mb-1">Confirmer le mot de passe</label> <input :type="showPassword ?'text' :'password'" v-model="confirmPassword" required placeholder="Confirmez votre mot de passe" class="w-full px-4 py-2.5 border border-[#01313E]/10 rounded-xl text-sm focus:outline-none focus:ring-2 focus:focus:border-[#E30046]" /> </div> <button type="submit" :disabled="loading" class="w-full py-3 px-4 bg-[#E30046] hover:bg-[#C7003D] text-white rounded-xl text-xs font-bold transition-colors flex items-center justify-center gap-2 -[#E30046]/20" > <Loader2 v-if="loading"class="w-4 h-4 animate-spin"/> <span>Changer le mot de passe</span> </button> </form> </div> </div> </template> 